    for (var j = 0; j < anchors.length; j++) {
      var a = anchors[j];
      if (selected && a.id === selected.id) continue;
      var dist = Math.hypot(a.x - view.player.x, a.y - view.player.y);
      if (view.camera === 'street' && dist > 60) continue;
      if (dist < best) { best = dist; nearest = a; }
