    }
    return out;
  }

  function makeRecord(sz, r) {
    return {
      id: sz.place.id, text: sz.place.name, x: r.x, y: r.y, width: r.w, height: r.h,
      fontCssPx: sz.fontCss, lines: sz.lines, selected: sz.sel,
      padX: sz.padX, padY: sz.padY, lineH: sz.lineH, fp: sz.fp
    };
  }

