function dpr() { return Math.min(window.devicePixelRatio || 1, 2); }

// Apply the requested width as a style hint, then measure the ACTUAL laid-out
// CSS size after the browser resolves max-width:100% / viewport constraints.
// The requested number is never used as the measured width.
function syncFrame() {
  canvas.style.width = state.requestedCss + 'px';
  var size = AmsterdamGeoRenderer.resolveFrameSize(canvas, {
    width: Number(state.requestedCss), height: 640
  });
  var scale = dpr();
  var bw = Math.max(1, Math.round(size.width * scale));
  var bh = Math.max(1, Math.round(size.height * scale));
  var key = bw + 'x' + bh + '@' + scale;
  // Resize the backing store only when the true size or DPR changes;
  // assigning canvas.width would otherwise wipe the context every frame.
  if (key !== backingKey) {
    canvas.width = bw;
    canvas.height = bh;
    backingKey = key;
  }
  frameSize = size;
  return size;
}

